<?php include '../auth/cek_login.php';include '../koneksi.php';$id=(int)($_GET['id']??0);$s=mysqli_prepare($conn,'SELECT * FROM mobil WHERE id=?');mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);$m=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$m)die('Data tidak ditemukan.');if(isset($_POST['update'])){$no=trim($_POST['nomor_polisi']);$merk=trim($_POST['merk']);$tipe=trim($_POST['tipe']);$tahun=(int)$_POST['tahun'];$warna=trim($_POST['warna']);$harga=(int)$_POST['harga_sewa'];$status=$_POST['status'];$s=mysqli_prepare($conn,'UPDATE mobil SET nomor_polisi=?,merk=?,tipe=?,tahun=?,warna=?,harga_sewa=?,status=? WHERE id=?');mysqli_stmt_bind_param($s,'sssisssi',$no,$merk,$tipe,$tahun,$warna,$harga,$status,$id);mysqli_stmt_execute($s);header('Location: index.php');exit;}?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Edit Mobil</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content form-page"><h1>Edit Mobil</h1><form method="post"><label>Nomor Polisi</label><input name="nomor_polisi" value="<?=htmlspecialchars($m['nomor_polisi'])?>" required><label>Merk</label><input name="merk" value="<?=htmlspecialchars($m['merk'])?>" required><label>Tipe</label><input name="tipe" value="<?=htmlspecialchars($m['tipe'])?>" required><label>Tahun</label><input type="number" name="tahun" value="<?=$m['tahun']?>" required><label>Warna</label><input name="warna" value="<?=htmlspecialchars($m['warna'])?>" required><label>Harga Sewa/Hari</label><input type="number" name="harga_sewa" value="<?=$m['harga_sewa']?>" required><label>Status</label><select name="status"><option <?=($m['status']=='Tersedia'?'selected':'')?>>Tersedia</option><option <?=($m['status']=='Disewa'?'selected':'')?>>Disewa</option></select><br><br><button name="update">Update</button> <a class="btn-delete" href="index.php">Kembali</a></form></div></body></html>
